"""Chroniques de la cabane à sucre: the Shinylive app.

Run it on your computer:   shiny run app/app.py --reload
Build the website:         shinylive export app docs

Where things live:
    app.py          this file: the page frame, and which page/season/day to show
    season_page.py  the "La saison" page
    years_page.py   the "Toutes les saisons" page
    charts.py       the four charts (drawn as SVG)
    components.py   small shared pieces: cards, big numbers, callouts
    french.py       how numbers and dates are written
    data.py         loads data.json and looks things up in it
    icons.py        the little icons
    clicks.js       passes taps on links/charts to the server
    styles.css      all colours (dark theme), fonts and spacing

How a tap works: a link's onclick calls go(...) or pickDay(...) in clicks.js.
That sets input.nav or input.pick_day here. The server updates `view`, `year`
or `day` below, and every part of the page that uses them redraws itself.
"""
from pathlib import Path

from shiny import App, reactive, render, ui

import charts
import season_page
import years_page
from data import FARM, LATEST_YEAR, season
from icons import ICON_SPRITE, icon

HERE = Path(__file__).parent
FONTS = ("https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,600"
         "&family=Source+Sans+3:wght@400;600;700&display=swap")


# ============================================================ layout
# The page frame: things that never change. The middle ("page") and the
# bottom tab bar are filled in by the server below.
#
# No ui.page_*() wrapper here on purpose: those add Bootstrap, whose own
# .card and button styles would fight with styles.css.

app_ui = ui.TagList(
    ui.head_content(
        ui.tags.title(FARM["name"]),
        ui.tags.meta(name="viewport", content="width=device-width, initial-scale=1, viewport-fit=cover"),
        ui.tags.meta(name="theme-color", content="#1a1512"),  # phone status bar colour = --bg
        ui.tags.link(rel="stylesheet", href=FONTS),
        ui.include_css(HERE / "styles.css"),
        ui.include_js(HERE / "clicks.js"),
    ),
    ui.busy_indicators.use(spinners=False, pulse=False),  # no loading spinners on every tap
    ICON_SPRITE,

    ui.tags.header(
        ui.div(
            ui.tags.a(
                ui.span(icon("leaf"), class_="brand-mark", aria_hidden="true"),
                ui.span(
                    ui.span("Chroniques sucrées", class_="brand-name"),
                    ui.span("Cinq saisons à la cabane Pinsept", class_="brand-sub"),
                ),
                class_="brand",
                onclick="go('season')",
            ),
            class_="topbar-inner",
        ),
        class_="topbar",
    ),

    # "shiny-report-size" makes the browser tell the server how wide this is,
    # so the charts can be drawn to fit the screen.
    ui.tags.main(ui.output_ui("page", class_="shiny-report-size"), class_="wrap"),

    ui.output_ui("tab_bar"),
)


# ============================================================ logic

def server(input, output, session):
    # What's on screen right now. Changing one of these redraws what depends on it.
    view = reactive.value("years")   # "season" or "years"
    year = reactive.value(2025)
    day = reactive.value(None)        # "2026-03-12", or None for the season's biggest day

    # --- taps (see clicks.js)

    @reactive.effect
    @reactive.event(input.nav)
    def follow_link():
        target = input.nav()          # e.g. {"view": "season", "year": 2024, "day": "2024-03-12"}
        view.set(target["view"])
        if target.get("year"):
            year.set(int(target["year"]))
        day.set(target.get("day"))

    @reactive.effect
    @reactive.event(input.pick_day)
    def follow_day():
        day.set(input.pick_day())

    # --- helpers

    def current_season():
        return season(year())

    def current_day():
        return season_page.default_day(current_season(), day())

    def width():
        return charts.chart_width(session.clientdata.output_width("page"))

    # --- the frame

    @render.ui
    def page():
        if view() == "years":
            return years_page.page()
        return season_page.page(current_season())

    @render.ui
    def tab_bar():
        def tab(name, icon_name, label):
            return ui.tags.a(
                icon(icon_name),
                ui.span(label),
                onclick=f"go('{name}')",
                aria_current="page" if view() == name else None,
            )

        return ui.tags.nav(
            tab("season", "book", "La saison"),
            tab("years", "chart", "Toutes les saisons"),
            class_="tabbar",
            aria_label="Sections",
        )

    # --- the season page's moving parts

    @render.ui
    def season_chart():
        return charts.season_chart(current_season(), current_day(), width())

    @render.ui
    def day_detail():
        return season_page.day_detail(current_season(), current_day())

    # --- the all-seasons charts

    @render.ui
    def yield_chart():
        return charts.yield_chart(width())

    @render.ui
    def timing_chart():
        return charts.timing_chart(width())

    @render.ui
    def sap_chart():
        return charts.sap_chart(width())


app = App(app_ui, server)

// Links and buttons in the app call one of these two functions
// (search the Python files for onclick= to see where).
// Each one hands the click over to the Python server, which then redraws the page.

// Go to a page:
//   go("years")                         the "Toutes les saisons" page
//   go("season")                        the season page, same year as before
//   go("season", 2024)                  the 2024 season
//   go("season", 2024, "2024-03-12")    the 2024 season, with 12 March picked
function go(view, year, day) {
  Shiny.setInputValue("nav", { view: view, year: year, day: day }, { priority: "event" });
  window.scrollTo(0, 0);
}

// Pick a day on the season page (from the chart or the arrow buttons).
function pickDay(day) {
  Shiny.setInputValue("pick_day", day, { priority: "event" });
}

"""Small building blocks that both pages reuse.

Each function returns a piece of HTML built with Shiny's ui.* tags. A few things
to know when reading these:
  - class_="..." becomes class="..." in the HTML (class is a Python keyword).
  - Plain text you pass in is escaped automatically, so logbook notes with
    "<" or "&" in them are safe.
  - ui.HTML("...") is the exception: it inserts its text as real HTML. It's
    used where a sentence needs <b>bold</b> words.
"""
from shiny import ui

from icons import icon


def card(*children, class_=""):
    """A white rounded box. Every section of both pages is one."""
    return ui.tags.section(*children, class_=f"card {class_}".strip())


def card_title(title, subtitle=None):
    """A section heading, with an optional grey line under it."""
    return ui.div(
        ui.div(
            ui.h2(title),
            ui.p(subtitle, class_="sub") if subtitle else None,
        ),
        class_="card-head",
    )


def stat(icon_name, label, value, note, unit=None):
    """One of the four big numbers at the top of each page."""
    return ui.div(
        ui.span(icon(icon_name), " ", label, class_="stat-label"),
        ui.span(value, ui.tags.small(unit) if unit else None, class_="stat-value num"),
        ui.span(note, class_="stat-note"),
        class_="stat",
    )


def callout(icon_name, sentence):
    """A highlighted sentence under a chart. The sentence may use <b>bold</b>."""
    return ui.div(icon(icon_name), ui.span(ui.HTML(sentence)), class_="callout")


def legend_item(swatch_class, label):
    """One coloured square + label in a chart legend."""
    return ui.span(ui.tags.i(class_=f"sw {swatch_class}"), label)

"""Loads data.json (built by scripts/build_data.py) and answers small questions about it.

Nothing in here builds HTML. It only looks things up in the data.

What one season looks like in data.json (abridged):
    {
      "year": 2026, "title": "...", "blurb": "...",
      "start": "2026-03-07", "end": "2026-04-11",      first and last fire
      "totalGal": 217.25, "butterPots": 115,
      "boilDays": 16, "logDays": 18, "lengthDays": 36,
      "sapDaysWindow": 11,      sap-weather days from 15 Feb to 20 Apr
      "sapDaysInSeason": 6,     sap-weather days between start and end
      "days": [ one entry per logbook line:
          {"date", "gal", "galText", "pots", "potsText", "bottled",
           "fireStart", "fireEnd", "notes", "lo", "hi"} ],
      "weather": [ one entry per calendar day, 15 Feb to 20 Apr:
          {"d": date, "lo": night low, "hi": day high, "p": rain mm,
           "s": snow cm, "sap": true if it was a sap-weather day} ]
    }
"""
import json
from datetime import date
from pathlib import Path

DATA = json.loads((Path(__file__).parent / "data.json").read_text(encoding="utf-8"))

FARM = DATA["farm"]                  # {"name": ..., "subtitle": ...}
SAP_RULE = DATA["sapDayRule"]        # {"nightBelowC": 0.0, "dayAboveC": 4.0}
SEASONS = DATA["seasons"]            # oldest first
LATEST_YEAR = SEASONS[-1]["year"]
UPDATED_ON = DATA["generated"][:10]  # "2026-11-21"

# Rough, fun estimates shown on the "Toutes les saisons" page
PANCAKE_STACKS_PER_GAL = 64          # ¼ cup of syrup per stack
POUDING_PER_GAL = 16                 # 1 cup of syrup per pouding chômeur (16 cups in a gallon)
SAP_TO_SYRUP_RATIO = 40              # 40 gallons of sap boil down to 1 of syrup


def season(year):
    """The season for a given year, e.g. season(2024)."""
    return next(s for s in SEASONS if s["year"] == year)


def average_gal():
    """Average syrup per season, in gallons."""
    return sum(s["totalGal"] for s in SEASONS) / len(SEASONS)


def all_days():
    """Every logbook day from every season, each one tagged with its year."""
    return [{**day, "year": s["year"]} for s in SEASONS for day in s["days"]]


def biggest_day(days):
    """The day with the most syrup. On a tie, the earliest one wins."""
    return max(days, key=lambda day: day["gal"] or 0)


def logbook_entry(s, iso):
    """The logbook line for a date, or None if nothing was written that day."""
    return next((day for day in s["days"] if day["date"] == iso), None)


def weather_on(s, iso):
    """The weather for a date, or None if it's outside 15 Feb to 20 Apr."""
    return next((w for w in s["weather"] if w["d"] == iso), None)


def on_shared_calendar(iso):
    """Move a date to the same month and day in 2024.

    This lets seasons from different years line up on one calendar.
    2024 is a leap year, so 29 Feb has a place too.
    """
    d = date.fromisoformat(iso)
    return date(2024, d.month, d.day)

"""The "La saison" page: one season's story and its day-by-day chart.

page() lays out the whole page. Two parts change when you pick a day, so
they're left as empty slots (ui.output_ui) that app.py fills in:
    "season_chart"  -> charts.season_chart()
    "day_detail"    -> day_detail() below
"""
from shiny import ui

from components import card, card_title, legend_item, stat
from data import SEASONS, average_gal, biggest_day, logbook_entry, weather_on
from french import NBSP, long_date, number, percent, plural, short_date, temperature, weekday
from icons import icon


def default_day(s, wanted_day):
    """The day to show: the one picked, or the season's biggest day."""
    if wanted_day and weather_on(s, wanted_day):
        return wanted_day
    return biggest_day(s["days"])["date"]


# ------------------------------------------------------------ whole page

def page(s):
    return ui.div(
        year_chips(s["year"]),
        hero(s),
        card(
            card_title(
                "La saison, jour par jour",
                "Chaque colonne est une journée. Touchez le graphique pour lire chaque journée.",
            ),
            ui.div(
                legend_item("sw-cedar", "Jour de coulée (gel, puis dégel)"),
                legend_item("sw-neutral", "Autres jours"),
                legend_item("sw-amber", "Sirop produit"),
                legend_item("sw-window", "Saison"),
                class_="legend",
            ),
            ui.output_ui("season_chart", class_="chart"),
            ui.div(ui.output_ui("day_detail"), id="detail", class_="detail"),
        ),
        footnote(s),
        class_="view",
    )


def year_chips(current_year):
    """The row of round year buttons at the top, newest first."""
    chips = [
        ui.tags.a(
            str(s["year"]),
            class_="chip",
            aria_current="true" if s["year"] == current_year else "false",
            onclick=f"go('season', {s['year']})",
        )
        for s in reversed(SEASONS)
    ]
    return ui.tags.nav(*chips, class_="chips", aria_label="Choisir une saison")


def hero(s):
    """Title, story and the four big numbers."""
    average = average_gal()
    vs_average = (s["totalGal"] - average) / average * 100
    best = biggest_day(s["days"])

    # The current season's butter count may still be growing
    still_going = s["year"] == SEASONS[-1]["year"] and "to date" in (s["days"][-1]["notes"] or "").lower()

    return card(
        ui.span(icon("leaf"), f" Saison {s['year']}", class_="kicker"),
        ui.h1(s["title"]),
        ui.p(s["blurb"], class_="lede") if s["blurb"] else None,
        ui.div(
            ui.span(icon("cal"), f" {short_date(s['start'])} → {short_date(s['end'])} {s['year']}"),
            ui.span(icon("clock"), f" {s['lengthDays']} jours entre le premier et le dernier feu"),
            class_="daterange",
        ),
        ui.div(
            stat("drop", "Sirop", number(s["totalGal"], 1), unit="gal", note=[
                ui.span(
                    ("+" if vs_average >= 0 else "−") + percent(vs_average),
                    class_="up" if vs_average >= 0 else "down",
                ),
                " par rapport à la moyenne",
            ]),
            stat("jar", "Beurre d'érable", number(s["butterPots"]), unit="pots",
                 note=f"pots de 500{NBSP}g" + (" (jusqu'ici)" if still_going else "")),
            stat("flame", "Journées de bouillage", s["boilDays"],
                 note=f"Record{NBSP}: {number(best['gal'], 2)}{NBSP}gal le {short_date(best['date'])}"),
            stat("snow", "Jours de coulée", s["sapDaysInSeason"], unit="jours",
                 note="gel la nuit, dégel le jour, pendant la saison"),
            class_="stats",
        ),
        class_="hero",
    )


def footnote(s):
    if s["totalGalSource"] == "logbook":
        where_total_comes_from = "Le total de la saison est celui inscrit dans le cahier."
    elif s["totalGalSource"] == "story":
        where_total_comes_from = "Le total de la saison a été entré à la main."
    else:
        where_total_comes_from = ("Aucun total de saison n'a été inscrit au cahier cette année; "
                                  "le total additionne donc les entrées quotidiennes.")
    return ui.p(
        where_total_comes_from,
        " Les barres quotidiennes montrent le premier nombre de gallons inscrit pour chaque journée "
        "(les cannes, les réserves et les reports ne sont pas comptés), alors elles ne donnent pas "
        "exactement le total. ",
        f"Météo{NBSP}: historique horaire d'Open-Meteo pour l'érablière. Minimum de nuit = l'heure la "
        f"plus froide en dehors de 9{NBSP}h à 18{NBSP}h; maximum de jour = l'heure la plus chaude "
        f"entre 9{NBSP}h et 18{NBSP}h.",
        class_="footnote",
    )


# ------------------------------------------------------------ the picked day

def day_title(s, iso, entry, w):
    """A short headline for the picked day."""
    best_gal = max(day["gal"] or 0 for day in s["days"])
    if entry:
        if iso == s["days"][0]["date"]:
            return "Premier feu de la saison"
        if iso == s["days"][-1]["date"]:
            return "Dernière journée de la saison"
        if entry["gal"] and entry["gal"] == best_gal:
            return "La plus grosse journée de la saison"
        if entry["gal"]:
            return f"{number(entry['gal'], 2)} {plural(entry['gal'], 'gallon', 'gallons')} de sirop"
        if entry["pots"]:
            return "Une journée de beurre d'érable"
        return "Une journée au cahier"
    sap_weather = w and w["sap"]
    if iso < s["start"]:
        return "Temps de coulée, mais pas encore de feu" if sap_weather else "Avant la saison"
    if iso > s["end"]:
        return "Après la dernière journée"
    return "Beau temps de coulée, rien d'inscrit au cahier" if sap_weather else "Une journée tranquille à la cabane"


def pill(*children, good=False):
    """A small rounded label, e.g. "Nuit −3 °C"."""
    return ui.span(*children, class_="pill good" if good else "pill")


def day_detail(s, iso):
    """The box under the chart: weather and logbook for the picked day."""
    entry = logbook_entry(s, iso)
    w = weather_on(s, iso)

    # Arrows jump to the previous / next logbook entry
    earlier = [day for day in s["days"] if day["date"] < iso]
    later = [day for day in s["days"] if day["date"] > iso]
    previous_day = earlier[-1]["date"] if earlier else None
    next_day = later[0]["date"] if later else None

    def arrow(target, icon_name, label):
        return ui.tags.button(
            icon(icon_name),
            type="button",
            class_="iconbtn",
            aria_label=label,
            disabled=None if target else True,
            onclick=f"pickDay('{target}')" if target else None,
        )

    pills = []
    if entry and entry["gal"]:
        pills.append(pill(icon("drop"), " ", ui.tags.b(f"{number(entry['gal'], 2)}{NBSP}gal")))
    if w:
        pills.append(pill(icon("snow"), " Nuit ", ui.tags.b(temperature(w["lo"]))))
        pills.append(pill(icon("sun"), " Jour ", ui.tags.b(temperature(w["hi"]))))
        if w["sap"]:
            pills.append(pill(icon("leaf"), " Jour de coulée", good=True))
        if w["s"] > 0:
            pills.append(pill("Neige au sol ", ui.tags.b(f"{w['s']}{NBSP}cm")))
        if w["p"] >= 1:
            pills.append(pill(icon("storm"), " Précipitations ", ui.tags.b(f"{number(w['p'], 1)}{NBSP}mm")))

    # Logbook values, shown exactly as written
    facts = []
    if entry:
        if entry["galText"]:
            facts.append(("Sirop", entry["galText"]))
        if entry["potsText"]:
            facts.append(("Beurre d'érable", entry["potsText"]))
        if entry["bottled"]:
            facts.append(("Bouteilles / cannes", entry["bottled"]))
        if entry["fireStart"] or entry["fireEnd"]:
            facts.append(("Feu", f"{entry['fireStart'] or '?'} → {entry['fireEnd'] or '?'}"))

    return ui.TagList(
        ui.div(
            ui.span(f"{weekday(iso)} · {long_date(iso)}", class_="detail-date"),
            ui.span(
                arrow(previous_day, "left", "Entrée précédente"),
                arrow(next_day, "right", "Entrée suivante"),
                class_="navbtns",
            ),
            class_="detail-top",
        ),
        ui.h3(day_title(s, iso, entry, w), style="margin-top:6px"),
        ui.div(*pills, class_="pills"),
        ui.div(ui.span(icon("note"), " Au cahier", class_="label"), entry["notes"], class_="journal")
        if entry and entry["notes"] else None,
        ui.tags.dl(*[[ui.tags.dt(k), ui.tags.dd(v)] for k, v in facts], class_="kv")
        if facts else None,
        ui.p("Rien au cahier pour cette journée. Utilisez les flèches pour aller à l'entrée la plus proche.",
             class_="sub", style="margin-top:12px")
        if not entry else None,
    )

/* Sugarhouse Craft: dark wood, amber and cedar.
   Every colour in the app comes from these variables (the charts use them too). */
:root {
  --bg: #1a1512;          /* page background */
  --card: #231c17;        /* card background */
  --card-2: #2b231d;      /* boxes inside cards */
  --line: #3a3029;        /* borders, grid lines */
  --line-2: #4a3d33;
  --ink: #f3ebe2;         /* main text */
  --ink-2: #d6c6b6;       /* softer text */
  --muted: #a8968a;       /* small grey text */
  --amber: #e8913a;       /* syrup, highlights */
  --amber-deep: #f5b26b;
  --amber-soft: #3a2817;
  --amber-tint: rgba(232, 145, 58, 0.14);
  --cedar: #74c48f;       /* green: sap weather */
  --cedar-soft: #1f3326;
  --bar-neutral: #5d5148; /* grey bars: other days */
  --cold: #8fb1d6;
  --shadow: 0 4px 14px -2px rgba(0, 0, 0, 0.4);
  --radius: 10px;
  --serif: "Playfair Display", Georgia, serif;
  --sans: "Source Sans 3", system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: dark;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 16px/1.5 var(--sans);
  padding-bottom: calc(72px + env(safe-area-inset-bottom, 0px));
  -webkit-tap-highlight-color: transparent;
}
a { color: inherit; }
/* Anything with an onclick (tabs, year chips, records, chart bars...) shows the hand cursor */
[onclick] { cursor: pointer; }
button { font: inherit; color: inherit; }
svg { display: block; }
.wrap { max-width: 760px; margin: 0 auto; padding: 16px; }
.loading { color: var(--muted); text-align: center; padding: 80px 0; font-style: italic; }

/* ---------- top bar ---------- */
.topbar {
  position: sticky; top: 0; z-index: 10;
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
  padding-top: env(safe-area-inset-top, 0px);
}
.topbar-inner { max-width: 760px; margin: 0 auto; padding: 10px 16px; }
.brand { display: flex; align-items: center; gap: 12px; text-decoration: none; }
.brand-mark {
  width: 40px; height: 40px; border-radius: 10px; display: grid; place-items: center;
  background: var(--amber); color: #fffaf2; flex: none;
}
.brand-mark svg { width: 24px; height: 24px; }
.brand-name { display: block; font: 700 clamp(16px, 4.6vw, 20px)/1.15 var(--serif); }
.brand-sub { display: block; font: 600 11px/1.4 var(--sans); letter-spacing: .08em; text-transform: uppercase; color: var(--cedar); }

/* ---------- tab bar ---------- */
.tabbar {
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 10;
  display: flex; justify-content: center; gap: 8px;
  background: color-mix(in srgb, var(--card) 92%, transparent);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  border-top: 1px solid var(--line);
  padding: 6px 16px calc(6px + env(safe-area-inset-bottom, 0px));
}
.tabbar a {
  flex: 0 1 180px; display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 6px 8px; border-radius: 10px; text-decoration: none;
  color: var(--muted); font: 600 12px/1.2 var(--sans); letter-spacing: .02em;
}
.tabbar a svg { width: 24px; height: 24px; }
.tabbar a { transition: color .15s, background-color .15s, box-shadow .15s; }
.tabbar a:hover { color: var(--ink); background: var(--card-2); box-shadow: inset 0 0 0 1px var(--line-2); }
/* The tab you're on stays amber, even when hovered */
.tabbar a[aria-current="page"],
.tabbar a[aria-current="page"]:hover { color: var(--amber); background: var(--amber-tint); }

/* ---------- type ---------- */
.kicker {
  display: inline-flex; align-items: center; gap: 6px;
  font: 600 12px/1.3 var(--sans); letter-spacing: .08em; text-transform: uppercase; color: var(--amber);
}
.kicker svg { width: 16px; height: 16px; }
h1, h2, h3 { font-family: var(--serif); margin: 0; letter-spacing: -0.01em; }
h1 { font-size: clamp(30px, 7vw, 44px); line-height: 1.1; font-weight: 700; margin: 8px 0 10px; text-wrap: balance; }
h2 { font-size: clamp(22px, 5vw, 26px); line-height: 1.2; font-weight: 600; }
h3 { font-size: 19px; line-height: 1.25; font-weight: 600; }
.lede { color: var(--ink-2); font-size: 17px; line-height: 1.55; margin: 0; text-wrap: pretty; }
.sub { color: var(--muted); font-size: 14px; margin: 4px 0 0; }
.num { font-variant-numeric: tabular-nums; }

/* ---------- cards ---------- */
.card {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 20px; margin: 0 0 16px;
}
.card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; margin-bottom: 14px; }
.hero { border-top: 4px solid var(--amber); }
.section-gap { height: 8px; }

/* ---------- year chips ---------- */
.chips {
  display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none;
  margin: 0 -16px 16px; padding: 2px 16px;
}
.chips::-webkit-scrollbar { display: none; }
.chip {
  flex: none; border: 1px solid var(--line-2); background: var(--card);
  border-radius: 999px; padding: 8px 16px; min-height: 40px;
  font: 600 15px/1 var(--sans); cursor: pointer; text-decoration: none;
  display: inline-flex; align-items: center;
}
.chip[aria-current="true"] { background: var(--amber); border-color: var(--amber); color: #fffaf2; }

/* ---------- stat tiles ---------- */
.stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 18px; }
@media (min-width: 640px) { .stats { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.stat {
  background: var(--card-2); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px;
  display: flex; flex-direction: column; gap: 2px; min-width: 0;
}
.stat-label { display: flex; align-items: center; gap: 6px; font: 600 11px/1.3 var(--sans); letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.stat-label svg { width: 15px; height: 15px; flex: none; color: var(--amber); }
.stat-value { font: 700 30px/1.1 var(--serif); font-variant-numeric: lining-nums tabular-nums; margin-top: 4px; }
.stat-value small { font: 600 14px var(--sans); color: var(--ink-2); margin-left: 3px; }
.stat-note { font-size: 13px; color: var(--muted); line-height: 1.35; }
.up { color: var(--cedar); font-weight: 600; }
.down { color: var(--amber); font-weight: 600; }

.daterange { display: flex; flex-wrap: wrap; gap: 6px 14px; color: var(--ink-2); font-size: 14px; margin-top: 14px; }
.daterange span { display: inline-flex; align-items: center; gap: 6px; }
.daterange svg { width: 16px; height: 16px; color: var(--muted); }

/* ---------- legend ---------- */
.legend { display: flex; flex-wrap: wrap; gap: 6px 14px; font-size: 13px; color: var(--ink-2); margin: 0 0 8px; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.sw { width: 12px; height: 12px; border-radius: 3px; display: inline-block; flex: none; }
.sw-amber { background: var(--amber); }
.sw-cedar { background: var(--cedar); }
.sw-neutral { background: var(--bar-neutral); }
.sw-window { background: var(--amber-tint); border: 1px solid var(--line-2); }

/* ---------- charts ---------- */
.chart { width: 100%; position: relative; touch-action: pan-y; }
.chart svg { width: 100%; height: auto; overflow: visible; }
.chart text { font-family: var(--sans); font-size: 11px; fill: var(--muted); }
.chart .lbl-strong { fill: var(--ink); font-weight: 700; font-size: 12px; }
.chart .grid { stroke: var(--line); stroke-width: 1; }
.chart .zero { stroke: var(--line-2); stroke-width: 1.25; }
.chart .hit { fill: transparent; cursor: pointer; }
.chart .sel { fill: var(--amber-tint); stroke: var(--amber); stroke-width: 1; stroke-dasharray: 3 3; }
.panel-label { font: 600 11px/1 var(--sans); letter-spacing: .07em; text-transform: uppercase; fill: var(--muted); }
.hint { font-size: 13px; color: var(--muted); margin: 8px 0 0; text-align: center; }

/* ---------- day detail ---------- */
.detail {
  margin-top: 14px; border: 1px solid var(--line-2); border-radius: 10px; background: var(--card-2);
  padding: 16px; scroll-margin-top: 80px;
}
.detail-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.detail-date { font: 600 12px/1.3 var(--sans); letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.navbtns { display: flex; gap: 6px; flex: none; }
.iconbtn {
  width: 40px; height: 40px; border-radius: 999px; border: 1px solid var(--line-2); background: var(--card);
  display: grid; place-items: center; cursor: pointer;
}
.iconbtn svg { width: 18px; height: 18px; }
.iconbtn:disabled { opacity: .35; cursor: default; }
.pills { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0 0; }
.pill {
  display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border-radius: 6px;
  background: var(--card); border: 1px solid var(--line); font-size: 14px; color: var(--ink-2);
}
.pill svg { width: 15px; height: 15px; }
.pill b { color: var(--ink); font-variant-numeric: tabular-nums; }
.pill.good { background: var(--cedar-soft); border-color: transparent; color: var(--cedar); font-weight: 600; }
.journal {
  margin: 14px 0 0; padding: 12px 14px; border-left: 3px solid var(--amber); background: var(--card);
  border-radius: 0 8px 8px 0; font-size: 16px; line-height: 1.5; color: var(--ink);
}
.journal .label { display: flex; align-items: center; gap: 6px; font: 600 11px/1.3 var(--sans); letter-spacing: .07em; text-transform: uppercase; color: var(--muted); margin-bottom: 4px; }
.journal .label svg { width: 14px; height: 14px; }
.kv { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; margin: 12px 0 0; font-size: 14px; }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; color: var(--ink); }

/* ---------- multi-season ---------- */
.callout {
  display: flex; gap: 10px; align-items: flex-start; margin-top: 14px; padding: 12px 14px;
  border-radius: 8px; background: var(--card-2); border: 1px solid var(--line); font-size: 15px; color: var(--ink-2);
}
.callout svg { width: 20px; height: 20px; color: var(--amber); flex: none; margin-top: 1px; }
.callout b { color: var(--ink); }

.fame { display: grid; gap: 10px; }
@media (min-width: 640px) { .fame { grid-template-columns: 1fr 1fr; } }
.fame a {
  display: flex; gap: 14px; padding: 14px; border-radius: 10px; text-decoration: none;
  background: var(--card-2); border: 1px solid var(--line);
}
.fame a[onclick]:hover { border-color: var(--amber); }  /* only clickable records */
.fame .ic { width: 42px; height: 42px; border-radius: 10px; display: grid; place-items: center; flex: none; background: var(--amber-soft); color: var(--amber); }
.fame .ic.cedar { background: var(--cedar-soft); color: var(--cedar); }
.fame .ic svg { width: 22px; height: 22px; }
.fame .k, .fame .v, .fame .s { display: block; }
.fame .k { font: 600 11px/1.3 var(--sans); letter-spacing: .08em; text-transform: uppercase; color: var(--amber); }
.fame .v { font: 700 21px/1.2 var(--serif); margin: 2px 0; }
.fame .s { font-size: 14px; color: var(--muted); line-height: 1.4; }

table.ledger { width: 100%; border-collapse: collapse; font-size: 14px; font-variant-numeric: tabular-nums; }
.ledger th, .ledger td { padding: 9px 6px; text-align: right; border-bottom: 1px solid var(--line); }
.ledger th:first-child, .ledger td:first-child { text-align: left; }
.ledger th { font: 600 11px/1.3 var(--sans); letter-spacing: .06em; text-transform: uppercase; color: var(--muted); }
.ledger tbody tr:nth-child(even) { background: var(--card-2); }
.ledger td:first-child a { font: 700 15px var(--serif); text-decoration: none; color: var(--amber); }
.scroll-x { overflow-x: auto; margin: 0 -20px; padding: 0 20px; }

.footnote { font-size: 13px; color: var(--muted); line-height: 1.5; margin: 8px 4px 24px; }

/* ---------- tooltip ---------- */
.tooltip {
  position: fixed; z-index: 50; pointer-events: none; max-width: 240px;
  background: var(--ink); color: var(--bg); border-radius: 8px; padding: 8px 10px;
  font-size: 13px; line-height: 1.4; box-shadow: 0 6px 18px rgba(0,0,0,.18);
}
.tooltip b { font-weight: 700; }

:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }
@media (prefers-reduced-motion: no-preference) {
  .view { animation: fade .25s ease-out; }
  @keyframes fade { from { opacity: 0; transform: translateY(4px); } }
}
